<div class="page-heading"><div><span class="eyebrow blue-text">BIBLIOTECA DE MÚSICAS</span><h1>Explore as cifras</h1><p>Encontre músicas por nome, momento ou tom.</p></div><span class="count-pill" data-result-count><?= count($songs) ?> <?= count($songs)===1 ? 'música' : 'músicas' ?></span></div>
<form class="filter-panel" action="<?= e(url('/buscar')) ?>" method="get" data-search-form><div class="filter-title"><?= icon('sliders',19) ?> Filtrar músicas</div><div class="filter-controls"><label class="field search-field"><span>Buscar</span><input name="q" placeholder="Nome ou artista" value="<?= e($query) ?>" data-search-query></label><label class="field"><span>Momento</span><select name="momento" data-search-category><option value="">Todos os momentos</option><?php foreach (array_unique(array_column($allSongs,'category')) as $moment): ?><option value="<?= e($moment) ?>" <?= $category===$moment ? 'selected' : '' ?>><?= e($moment) ?></option><?php endforeach; ?></select></label><label class="field"><span>Tom</span><select name="tom" data-search-key><option value="">Todos os tons</option><?php foreach (array_unique(array_column($allSongs,'key')) as $note): ?><option value="<?= e($note) ?>" <?= $key===$note ? 'selected' : '' ?>><?= e($note) ?></option><?php endforeach; ?></select></label></div></form>
<div class="list-heading"><h2>Resultados</h2><span data-result-caption><?= count($songs) ?> <?= count($songs)===1 ? 'encontrada' : 'encontradas' ?></span></div>
<div class="song-grid" data-search-results><?php $visibleIds=array_column($songs,'id'); foreach ($allSongs as $song) partial('song-card', ['song'=>$song,'hidden'=>!in_array($song['id'],$visibleIds,true)]); ?></div>
<div class="empty-state" data-search-empty <?= $songs ? 'hidden' : '' ?>><span class="soft-icon"><?= icon('search',26) ?></span><h2>Nenhuma música encontrada</h2><p>Tente outro nome, tom ou momento.</p><a class="secondary-button" href="<?= e(url('/buscar')) ?>">Limpar filtros</a></div>
